import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"Phase 5 · Memory and Capability Evolution","description":"Let the system accumulate context and improve methods, with every change visible, correctable, and reversible.","frontmatter":{"title":"Phase 5 · Memory and Capability Evolution","description":"Let the system accumulate context and improve methods, with every change visible, correctable, and reversible.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-5.md","filePath":"en/delivery/stage-5.md","lastUpdated":1794305977000}'),l={name:"en/delivery/stage-5.md"};function i(n,e,s,d,h,m){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="phase-5-·-memory-and-capability-evolution" tabindex="-1">Phase 5 · Memory and Capability Evolution <a class="header-anchor" href="#phase-5-·-memory-and-capability-evolution" aria-label="Permalink to &quot;Phase 5 · Memory and Capability Evolution&quot;">​</a></h1><p>See <a href="/hearth-os/en/delivery/status.html">Phase 2–6 Delivery Status</a> for implemented scope, verified paths, and deliberate gaps.</p><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Implemented code loop:</strong> Memory candidates, recall, correction, conflict handling, consolidation, forgetting propagation, tombstones, and export; method candidates are generated from finished task traces and pass through trial evidence, evaluation, promotion, rejection, and rollback; skills have scoped permissions, lifecycle, stale cleanup, and rollback; durable single-layer delegation, handoff generations, and sandbox boundaries also exist.</li><li><strong>Still open:</strong> Real long-term memory use, error-memory and error-method drills, before/after production comparison, real multi-executor stress, and the full 5.4 acceptance. See <a href="/hearth-os/en/delivery/status.html">Phase 2–6 delivery status</a>.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Phase 5 lets Hearth accumulate personal context and improve how it works, but every memory must be visible, correctable, forgettable, and exportable, and every new method must be evaluated, trialed, and reversible.</p><p>This phase has four steps:</p><table tabindex="0"><thead><tr><th>Step</th><th>Goal</th></tr></thead><tbody><tr><td><a href="/hearth-os/en/delivery/stage-5/5-1.html">5.1 Create visible memory</a></td><td>Remember useful information and explain its source and use.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-5/5-2.html">5.2 Correct, forget, and export memory</a></td><td>Wrong memories can be fixed, sensitive information can be forgotten, and all data can be taken away.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-5/5-3.html">5.3 Summarize and evaluate reusable methods</a></td><td>New methods start as candidates and are adopted only after evaluation and a small trial.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-5/5-4.html">5.4 Accept memory and evolution</a></td><td>Prove memory and new methods are useful without becoming uncontrolled or irreversible.</td></tr></tbody></table><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>First create memory that can be viewed and corrected.</li><li>Then handle forgetting, export, and sensitive-information boundaries.</li><li>Then summarize reusable methods from real tasks.</li><li>Finally accept with evaluation, small-scale trials, and rollback.</li></ol>',10)])])}const p=a(l,[["render",i]]);export{u as __pageData,p as default};
